import hashlib
import time
import sys
import os

def hash_file(filepath):
    """Hash una ruta del archivo usando SHA-256."""
    try:
        with open(filepath, 'rb') as f:
           sha256_hash = hashlib.sha256()
           while True:
               chunk = f.read(4096)
               if not chunk:
                   break
               sha256_hash.update(chunk)
           return sha256_hash.hexdigest()
    except FileNotFoundError:
        print(f"No se encontró el archivo: {filepath}")
        return None


def main():
    """Implementa la función principal para ejecutar la función hash."""
    if len(sys.argv) > 1:
        filepath = sys.argv[1]
    else:
        filepath = 'test.txt' #Usa un archivo por defecto.

    hash_value = hash_file(filepath)
    print(f"Hash: {hash_value}")
    if hash_value:
        print(f"Archivo: {filepath}")

if __name__ == "__main__":
    main()
```

Este código es un shell de hash de archivo básico.  La función `hash_file` lee un archivo en modo de lectura binaria y calcula el hash SHA-256 del contenido. Si el archivo no existe, imprime el error y retorna None. La función `main` recibe el nombre del archivo especificado a través de la línea de comandos. De lo contrario, usa un archivo por defecto.
